"""Loop an existing MCAP recording to a live Foxglove WebSocket server."""

from __future__ import annotations

import json
import threading
import time
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Optional
from urllib.parse import quote

import foxglove
from mcap.reader import make_reader

from . import ui

WEBSOCKET_URL = "ws://localhost:8765"

# Nanoseconds per second, for converting MCAP log times (unix-epoch ns).
_NS_PER_S = 1_000_000_000

# When the recorded gap between two messages is larger than this, clamp the
# sleep so a sparse stretch in the file doesn't stall playback for minutes.
_MAX_GAP_S = 1.0

# Loop iteration gap
_LOOP_GAP_NS = 100_000_000  # 0.1s

# The takeoff event is placed this many seconds into the recording.
_TAKEOFF_OFFSET_S = 3.0

# A live-only marker topic that lets the Foxglove app identify this stream as the onboarding quickstart and exclude it from activation metrics.
_DEVICE_NAME_TOPIC = "/foxglove_sample_stream/device_name"
_DEVICE_NAME_VALUE = "onboarding-quickstart-wizard"
_DEVICE_NAME_INTERVAL_S = 0.2


@dataclass
class PlaybackResult:
    """Timing of a completed playback, used to upload and to place the event."""

    mcap_path: str
    start: datetime
    end: datetime
    takeoff_at: datetime


@dataclass
class LivePlayback:
    """A running live stream: the recording's timing plus handles to stop it."""

    result: PlaybackResult
    #: True when a Foxglove viewer subscribed before playback started.
    connected: bool
    server: "foxglove.WebSocketServer"
    _stop: threading.Event
    _thread: threading.Thread
    _device_name_thread: threading.Thread
    _handle: object

    def stop(self) -> None:
        """Stop looping, join the replay and marker threads, close the file, and stop the server."""
        self._stop.set()
        self._thread.join()
        self._device_name_thread.join()
        try:
            self._handle.close()
        except Exception:  # closing is best-effort on shutdown
            pass
        self.server.stop()


def _to_utc(log_time_ns: int) -> datetime:
    """Convert an MCAP log time (unix-epoch nanoseconds) to an aware UTC datetime."""
    return datetime.fromtimestamp(log_time_ns / _NS_PER_S, tz=timezone.utc)


def _now_utc() -> datetime:
    return datetime.now(timezone.utc)


def read_time_span(mcap_path: str) -> tuple[int, int]:
    """Return the recording's (start, end) log times in unix-epoch nanoseconds, or (0, 0) if no statistics."""
    with open(mcap_path, "rb") as handle:
        summary = make_reader(handle).get_summary()
    stats = summary.statistics if summary else None
    if stats is None:
        return 0, 0
    return stats.message_start_time, stats.message_end_time


def compute_now_anchor(mcap_path: str) -> tuple[int, datetime]:
    """Re-anchor the recording to end at "now"; return (offset_ns, takeoff_at)."""
    start_ns, end_ns = read_time_span(mcap_path)
    now = _now_utc()
    offset_ns = int(now.timestamp() * _NS_PER_S) - end_ns if end_ns else 0
    start = _to_utc(start_ns + offset_ns) if start_ns else now
    return offset_ns, start + timedelta(seconds=_TAKEOFF_OFFSET_S)


class _StartOnSubscribe(foxglove.ServerListener):
    """Signals ``started`` the first time any Foxglove client subscribes to a channel."""

    def __init__(self, started: threading.Event) -> None:
        super().__init__()
        self._started = started

    def on_subscribe(self, client: object, channel: object) -> None:
        self._started.set()


def _wait_for_subscriber(started: threading.Event, timeout_s: float) -> None:
    deadline = time.monotonic() + timeout_s
    print("Waiting for Foxglove to connect", end="", flush=True)
    while not started.is_set() and time.monotonic() < deadline:
        started.wait(timeout=1.0)
        if not started.is_set():
            print(".", end="", flush=True)
    print()
    if started.is_set():
        ui.success("Foxglove connected.")
    else:
        ui.warn("No viewer connected in time; starting anyway.")


def _view_url(
    server: object,
    base_url: Optional[str],
    layout_id: Optional[str],
    org_slug: Optional[str] = None,
    project_id: Optional[str] = None,
) -> str:
    """Build a Foxglove link that opens connected to this live WebSocket server."""
    if not base_url:
        return server.app_url(layout_id=layout_id)
    query = f"ds=foxglove-websocket&ds.url={quote(WEBSOCKET_URL, safe='')}&onboarding=1"
    if layout_id:
        query += f"&layoutId={layout_id}"
    base = base_url.rstrip("/")
    if org_slug and project_id:
        return f"{base}/{org_slug}/p/{project_id}/view?{query}"
    return f"{base}?{query}"


def _build_channels(reader: object) -> "tuple[dict[int, foxglove.Channel], int, int]":
    """Mirror the file's channels/schemas as live channels, returning them with the start and end log times."""
    summary = reader.get_summary()
    if summary is None:
        raise RuntimeError("MCAP file has no summary section; cannot read its channels.")

    live_channels: dict[int, foxglove.Channel] = {}
    for channel_id, channel in summary.channels.items():
        schema_record = summary.schemas.get(channel.schema_id)
        schema = None
        if schema_record is not None:
            schema = foxglove.Schema(
                name=schema_record.name,
                encoding=schema_record.encoding,
                data=schema_record.data,
            )
        live_channels[channel_id] = foxglove.Channel(
            channel.topic,
            message_encoding=channel.message_encoding,
            schema=schema,
        )

    stats = summary.statistics
    start_ns = stats.message_start_time if stats else 0
    end_ns = stats.message_end_time if stats else 0
    return live_channels, start_ns, end_ns


def _publish_device_name_loop(
    channel: "foxglove.Channel", stop_event: threading.Event
) -> None:
    """Log the constant device name every ``_DEVICE_NAME_INTERVAL_S`` seconds until stopped."""
    payload = json.dumps({"name": _DEVICE_NAME_VALUE}).encode("utf-8")
    while not stop_event.is_set():
        channel.log(payload, log_time=time.time_ns())
        if stop_event.wait(_DEVICE_NAME_INTERVAL_S):
            return


def _replay_loop(
    reader: object,
    live_channels: "dict[int, foxglove.Channel]",
    start_ns: int,
    end_ns: int,
    stop_event: threading.Event,
) -> None:
    """Replay the recording end-to-end, restarting until ``stop_event`` is set."""
    duration_ns = max(end_ns - start_ns, 0)
    loop_index = 0
    while not stop_event.is_set():
        offset_ns = loop_index * (duration_ns + _LOOP_GAP_NS)
        previous_log_time: Optional[int] = None
        for _schema, channel, message in reader.iter_messages(log_time_order=True):
            if stop_event.is_set():
                return
            live_channel = live_channels.get(channel.id)
            if live_channel is None:
                continue

            if previous_log_time is not None:
                gap_s = (message.log_time - previous_log_time) / _NS_PER_S
                if gap_s > 0 and stop_event.wait(min(gap_s, _MAX_GAP_S)):
                    return
            previous_log_time = message.log_time

            live_channel.log(message.data, log_time=message.log_time + offset_ns)
        loop_index += 1


def play(
    mcap_path: str,
    *,
    view_base_url: Optional[str] = None,
    layout_id: Optional[str] = None,
    org_slug: Optional[str] = None,
    project_id: Optional[str] = None,
    wait_for_subscriber: bool = True,
    wait_timeout_s: float = 300.0,
) -> LivePlayback:
    """Replay ``mcap_path`` to a live Foxglove WebSocket server, looping forever until stopped."""
    started = threading.Event()

    handle = open(mcap_path, "rb")
    try:
        reader = make_reader(handle)
        # Create channels first so they are advertised when the viz connects.
        live_channels, start_ns, end_ns = _build_channels(reader)
        device_name_channel = foxglove.Channel(
            _DEVICE_NAME_TOPIC,
            message_encoding="json",
            schema=foxglove.Schema(
                name="foxglove_wizard_sample/DeviceName",
                encoding="jsonschema",
                data=json.dumps(
                    {"type": "object", "properties": {"name": {"type": "string"}}}
                ).encode("utf-8"),
            ),
        )

        server = foxglove.start_server(server_listener=_StartOnSubscribe(started))
        view_url = _view_url(server, view_base_url, layout_id, org_slug, project_id)
        ui.info("Head back to Foxglove and click Connect to see the data streaming live.")
        ui.detail("Didn't start from Foxglove? Open this link:")
        ui.link(view_url)

        if wait_for_subscriber:
            _wait_for_subscriber(started, wait_timeout_s)

        start = _to_utc(start_ns) if start_ns else _now_utc()
        end = _to_utc(end_ns) if end_ns else _now_utc()
        takeoff_at = start + timedelta(seconds=_TAKEOFF_OFFSET_S)
        ui.detail(f"Press {ui.stop_hint()} to stop streaming.")

        stop_event = threading.Event()
        thread = threading.Thread(
            target=_replay_loop,
            args=(reader, live_channels, start_ns, end_ns, stop_event),
            name="mcap-replay-loop",
            daemon=True,
        )
        thread.start()

        device_name_thread = threading.Thread(
            target=_publish_device_name_loop,
            args=(device_name_channel, stop_event),
            name="device-name-publisher",
            daemon=True,
        )
        device_name_thread.start()
    except BaseException:
        handle.close()
        raise

    result = PlaybackResult(
        mcap_path=mcap_path, start=start, end=end, takeoff_at=takeoff_at
    )
    return LivePlayback(
        result=result,
        connected=started.is_set(),
        server=server,
        _stop=stop_event,
        _thread=thread,
        _device_name_thread=device_name_thread,
        _handle=handle,
    )
